Python sample (requests-like HTTP/async):
from redwood_sdk import Client
client = Client(transport_config={
    'connect_timeout': 3.0,
    'total_timeout': 30.0,
    'pool_size': 20,
    'idle_ttl_seconds': 60,
    'keepalive_interval_seconds': 30,
})
# streaming helper (auto-resume if server returns resume_token)
with client.stream('generate') as stream:
    for chunk in stream:
        process(chunk)

# If you need unsafe retries for non-idempotent route:
resp = client.request('chat.completions', body, unsafe_retries=False)
TypeScript sample (fetch / Node):
import { RedwoodClient } from '@redwood/inference'
const client = new RedwoodClient({
  transport: {
    connectTimeoutMs: 3000,
    totalTimeoutMs: 30000,
    poolSize: 12,
    idleTtlMs: 60000,
    keepaliveIntervalMs: 30000,
  }
})
// streaming with explicit resume token handling
const stream = client.stream('generate')
stream.on('data', (chunk) => { /* user ack logic */ })
stream.on('error', async (err) => { /* SDK will attempt reconnect if resumeToken available */ })
Go sample (http2/grpc style):
cfg := sdk.DefaultConfig()
cfg.Transport.ConnectTimeout = 3 * time.Second
cfg.Transport.TotalTimeout = 30 * time.Second
cfg.Transport.PoolSize = 30
cfg.Transport.IdleTTL = 60 * time.Second
client := sdk.New(cfg)
// streaming: use ResumeToken from last message to reconnect
stream, err := client.Stream(ctx, 'generate')
for {
    msg, err := stream.Recv()
    if err == io.EOF { break }
    if isTransient(err) {
        stream, err = client.ResumeStream(ctx, resumeToken)
        continue
    }
    handle(msg)
}
